      iconHtml = '<div class="wi-snow-group"><div class="wi-cloud"></div><div class="wi-snowflakes"><div class="wi-flake" style="animation-delay: 0s"></div><div class="wi-flake" style="animation-delay: 0.5s"></div><div class="wi-flake" style="animation-delay: 0.2s"></div></div></div>';
